SELECT m.machine_name,p.product_name,SUM(f.quantity_good) good_units FROM fact_production f JOIN dim_machine m USING(machine_key) JOIN dim_product p USING(product_key) JOIN dim_operation_taxonomy o USING(operation_key) JOIN dim_shift s USING(shift_key) WHERE m.machine_type='CNC lathe' AND o.subclass_label='Точіння' AND s.shift_name='Ранкова' GROUP BY m.machine_name,p.product_name;
